// --- prototypes generated by arduino_sim.py (the Arduino IDE/Tinkercad do the same) ---
void setup();
void loop();
// ex04 -- opposition: write the two pins with opposite values in the same step
const int EXT_LED = 5;
const int INT_LED = LED_BUILTIN;

void setup() {
  pinMode(EXT_LED, OUTPUT);
  pinMode(INT_LED, OUTPUT);
}

void loop() {
  digitalWrite(EXT_LED, HIGH);
  digitalWrite(INT_LED, LOW);
  delay(500);
  digitalWrite(EXT_LED, LOW);
  digitalWrite(INT_LED, HIGH);
  delay(500);
}
